
.header {
  padding: 10px 12px;
  cursor: pointer;
  user-select: none;
  background-color: var(--c-surface);
  border-bottom: 1px solid var(--c-border);
  transition: var(--t-theme);

  &:hover {
    background-color: var(--c-surface-2);
  }
}

.row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.who {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.level-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 999px;
  background-color: var(--c-surface-2);
  border: 1px solid var(--c-primary-dim);
  color: var(--c-primary);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.5px;
  white-space: nowrap;
}

.lesson {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 13px;
  color: var(--c-text);
}

.right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.mode-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 2px 8px;
  border-radius: 6px;
  background-color: var(--c-surface-2);
  border: 1px solid var(--c-border);
  color: var(--c-text-muted);
  font-size: 11px;
  white-space: nowrap;
}

.chevron {
  font-size: 11px;
  color: var(--c-text-muted);
  transition: transform 0.25s ease;

  &.flipped {
    transform: rotate(180deg);
  }
}

.gauge {
  margin-top: 8px;
}

.gauge-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 3px;
}

.gauge-label {
  font-size: 10px;
  letter-spacing: 1px;
  color: var(--c-text-muted);

  i {
    color: var(--c-primary);
  }
}

.gauge-num {
  font-family: var(--font-num);
  font-size: 13px;
  font-weight: 700;
  color: var(--c-primary);
}

.gauge-den {
  font-size: 10px;
  font-weight: 400;
  color: var(--c-text-muted);
}

.track {
  position: relative;
  height: 8px;
  border-radius: 4px;
  background-color: var(--c-surface-2);
  overflow: visible;
}

.fill {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--c-primary-dim), var(--c-primary));
  transition: width 0.6s ease;
}

.tick {
  position: absolute;
  top: -2px;
  width: 2px;
  height: 12px;
  border-radius: 1px;
  background-color: var(--c-border);
  transform: translateX(-1px);
  transition: background-color 0.4s ease;

  &.reached {
    background-color: var(--c-primary-dim);
  }

  &.next {
    background-color: var(--c-accent);
    box-shadow: 0 0 4px var(--c-accent);
  }
}

.ticks-row {
  position: relative;
  height: 12px;
}

.tick-label {
  position: absolute;
  transform: translateX(-50%);
  font-family: var(--font-num);
  font-size: 9px;
  color: var(--c-text-muted);
}
