
.section {
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: var(--t-theme);
}

.counters {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.counter {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-radius: 6px;
  background-color: var(--c-surface-2);
  border: 1px solid var(--c-border);

  i {
    color: var(--c-primary);
    font-size: 12px;
  }
}

.c-label {
  font-size: 11px;
  color: var(--c-text-muted);
}

.c-value {
  margin-left: auto;
  font-family: var(--font-num);
  font-size: 15px;
  font-weight: 700;
  color: var(--c-text);
}

.scene-row {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 11px;
  color: var(--c-text-muted);
}

.scene-item {
  display: inline-flex;
  align-items: center;
  gap: 5px;

  i {
    color: var(--c-primary-dim);
  }
}
