
.panel {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  background-color: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  overflow: hidden;
  font-family: var(--font-main);
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.45;
  transition: var(--t-theme), box-shadow 0.6s ease;
}

.panel-body {
  padding: 10px 12px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
