
.section {
  background-color: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 8px 10px;
  transition: var(--t-theme);
}

.section-head {
  font-family: var(--font-num);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: var(--c-primary);
  margin-bottom: 8px;
}

.section-sub {
  font-family: var(--font-main);
  font-weight: 400;
  font-size: 10px;
  color: var(--c-text-muted);
  letter-spacing: 0;
}

.ladder {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.level-row {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 8px;
  border: 1px solid var(--c-border);
  border-radius: 6px;
  background-color: var(--c-surface-2);
  transition: var(--t-theme);

  &.current {
    border-color: var(--c-primary-dim);
    box-shadow: inset 2px 0 0 var(--c-primary);
  }

  &.locked {
    opacity: 0.55;
  }
}

.level-tag {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 700;

  i {
    font-size: 9px;
    color: var(--c-text-muted);
  }

  .current & i.fa-circle {
    color: var(--c-primary);
  }
}

.level-name {
  letter-spacing: 1px;
  color: var(--c-text);
}

.level-req {
  font-family: var(--font-num);
  font-size: 10px;
  color: var(--c-accent);
}

.lessons {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

.lesson-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 11px;
  border: 1px solid var(--c-border);
  white-space: nowrap;

  i {
    font-size: 8px;
  }

  &.done {
    border-color: transparent;
    background-color: rgba(143, 175, 126, 0.16);
    color: var(--c-good);
  }

  &.current {
    border-color: var(--c-primary);
    color: var(--c-primary);
    font-weight: 700;

    i {
      color: var(--c-primary);
    }
  }

  &.pending {
    color: var(--c-text-muted);
    border-style: dashed;
  }
}
